package net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRuleMinLevelOptions;

class MinLevelVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property min level of observed alert rule ")
  void test_min_level_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> MinLevelVO.tryFrom("_ERROR_"));
    Assertions.assertEquals(ObservedAlertRuleMinLevelOptions.ERROR,
        MinLevelVO.tryFrom("ERROR").getMinLevel());
    Assertions.assertThrows(ConstraintException.class, () -> MinLevelVO.tryFrom(null));
    Assertions.assertEquals(ObservedAlertRuleMinLevelOptions.ERROR,
        MinLevelVO.from(ObservedAlertRuleMinLevelOptions.ERROR).getMinLevel());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MinLevelVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedAlertRuleMinLevelOptions.ERROR + "]",
        MinLevelVO.from(ObservedAlertRuleMinLevelOptions.ERROR).toString());
  }
}
